def get_Min_Squares(n):
    # Initialize variables
    min_squares = float('inf')
    for i in range(1, int(n**0.5)+1):
        if n % i == 0:
            square = i * i
            remaining = n - square
            if square < min_squares:
                min_squares = square
            if remaining > 0:
                min_squares = min(min_squares, square + remaining)
    return min_squares
