def max_sum(triangle, r):
    # Initialize the current row as the last element of the current row in the list
    curr_row = triangle[r]

    # Iterate through all possible positions for the next row
    for i in range(r-1, -1, -1):
        for j in range(i+1):
            if j == 0:
                # If there's no cell below, set its value to infinity
                triangle[i][j] = float('inf')
            elif j == i:
                # If there's no cell on top, set its value to zero
                triangle[i][j] = 0
            else:
                # Otherwise, take the maximum of the two adjacent cells
                triangle[i][j] = max(curr_row[j-1], curr_row[j])

    # Return the maximum value found in the last row of the triangle
    return max(triangle[0])
```

