def check_triplet(arr, n, k):
    # Sort the array
    arr.sort()

    # Iterate through all possible pairs (i, j)
    for i in range(n-2):
        if i > 0 and arr[i] == arr[i-1]:
            continue

        j = i + 1
        l = n - 1

        while j < l:
            current_sum = arr[i] + arr[j]

            if current_sum == k:
                return True

            elif current_sum < k:
                j += 1

            else:
                l -= 1

    return False
```

