def modular_inverse(arr, n, m):
    # Calculate the greatest common divisor (GCD) using Euclidean algorithm
    def gcd(a, b):
        while(b):
            a, b = b, a % b

        return abs(a)

    # Compute the modular multiplicative inverse using Extended Euclidean Algorithm
    def modinv(a, m):
        return (a % m) * (-1) % m

    # Find the GCD of each element in the array with m
    for i in range(n):
        if (gcd(i, m)) != 1:
            return 0

    # If all elements have their modular inverses, return their sum modulo m
    return (sum(x % m for x in arr)) % m
```

