def is_subset_sum(arr, n, k):
    # Initialize a dictionary to store sums up to each index as keys
    dp = [False] * (k + 1)

    # Fill the dp array
    for i in range(1, k+1):
        if i >= len(arr):
            break
        dp[i] = True

        for j in range(i, min(i+3, len(arr))):
            if arr[j] <= i:
                dp[i] = dp[i] or (dp[i-arr[j]] == True)

    return dp[k]
```

