def longest_common_subsequence(seq1, seq2, l, r):
    # Initialize the matrix of lengths of longest common subsequences
    dp = [[0] * (r + 1) for _ in range(l + 1)]

    # Fill the matrix
    for i in range(1, l+1):
        for j in range(1, r+1):
            if seq1[i-1] == seq2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1

            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[l][r]
```

