def count_no_of_ways(n, k):
    # Initialize a list where each index represents a different color
    colors = ['.' for _ in range(k)]

    def backtrack(index, used_colors):
        if index == n:
            return 1

        count = 0
        for i in range(len(colors)):
            if (i != index) and (colors[i] != '.' and (used_colors & (1 << i))):
                count += backtrack(index + 1, (colors[i] == colors[index]) * (1 << i))

        return count

    return backtrack(0, 0)
```

