def get_total_number_of_sequences(n, m):
    # Initialize a list of size n+1 with all elements set to 0
    dp = [0] * (n + 1)

    # Iterate through each possible starting value for the first element
    for i in range(1, n + 1):
        # Iterate through each possible value for the second element
        for j in range(i + 1):
            if j <= 2 * i:
                # Calculate the maximum value for the current sequence
                max_val = min(j, 2 * i - j)

                # Update the count of valid sequences ending at i
                dp[i] += dp[max_val]

        # After filling the DP table, update it by setting dp[i] to 1 for all i >= n
        for k in range(n, -1, -1):
            if k > i:
                break
            dp[k] += dp[k-1]

    return dp[n]
```

