def find_minimum_range(arrays):
    # Sort each array
    for i in range(len(arrays)):
        arrays[i] = sorted(arrays[i])

    # Initialize variables
    min_diff = float('inf')
    start_index = -1
    end_index = -1

    # Iterate through all possible starting points for the minimum range
    for i in range(len(arrays[0])):
        for j in range(i+1, len(arrays[0])):
            current_diff = abs(j-i)

            # Check if this difference can form a valid range with any other array
            for k in range(len(arrays)):
                if k != i and k != j:
                    next_array = arrays[k]

                    if current_diff + sum(next_array[:j]) <= max(next_array[j:]) + current_diff:
                        if next_array[j] - next_array[i] < min_diff:
                            min_diff = next_array[j] - next_array[i]
                            start_index = i
                            end_index = j

    return (start_index, end_index)
```

