```python
def solve(A, N):
    # Calculate the number of inversions using merge sort
    def merge_sort(arr):
        if len(arr) <= 1:
            return arr

        mid = len(arr) // 2
        left_half = merge_sort(arr[:mid])
        right_half = merge_sort(arr[mid:])

        return merge(left_half, right_half)

    def merge(left, right):
        result = []
        i = j = 0

        while i < len(left) and j < len(right):
            if left[i] > right[j]:
                result.append(left[i])
                i += 1
            else:
                result.append(right[j])
                j += 1

        result.extend(left[i:])
        result.extend(right[j:])

        return result

    # Counting inversions using two pointers
    def count_inversions(arr):
        i = 0
        j = 0
        k = 0
        while i < len(arr) and j < len(arr):
            if arr[i] > arr[j]:
                k += len(arr) - i
                break
            i += 1
        else:
            k += len(arr)

        return k

    # Check if the counts of inversions are equal
    return count_inversions(merge_sort(A)) == N
```

