    max_val = int(max(s), 10)

    # Initialize a dictionary to store counts of valid substrings
    count = {}

    # Iterate through all possible starting indices for the first digit
    for i in range(len(s)):
        num = int(s[i:])

        # If there's enough room left after including this digit
        if len(num) > n - i:
            continue

        # Calculate the remaining part after excluding the current digit
        rest = num[:n - i]

        # Add the count of valid substrings ending at 'rest' to the result
        if rest not in count:
            count[rest] = 0

        count[rest] += 1

    return len(count)
