def get_Min_Squares(n):
    # Calculate the maximum possible side length of a square that can be used
    max_side_length = (n // 2) ** 2

    # If n is less than 4, it's impossible to form a square
    if n < 4:
        return 0

    # Iterate through all possible values of side length
    for i in range(1, max_side_length + 1):
        if i * i > n:
            break
        elif (n - i * i) % i == 0:
            return (n - i * i) // i + 1

    return 0
```

