def lps(s):
    # Initialize the length of the input string
    n = len(s)

    # Create a dictionary to store the lengths of longest palindromes ending at each character
    dp = {}

    # Function to expand around characters to find the longest palindrome
    def expand_around_center(left, right):
        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1

        return right - left - 1

    # Iterate through all possible pairs of indices that form parts of palindromes
    for i in range(n):
        for j in range(i, n):
            # Check if the substring from index i to j forms a palindrome
            if i > 0 and j > i and s[i] == s[j]:
                l = expand_around_center(i, j)

                # Update the maximum length found so far
                if l > len(dp[s[i]:s[j+1]]):
                    dp[s[i:j+1]] = l

    return len(max(dp.keys(), key=len))
```

