def find_ways(n):
    # Initialize a list to store the number of ways to achieve each sum up to n
    ways = [0] * (n + 1)

    # Base case: there's one way to reach sum 0 (by not selecting any item)
    for i in range(0, n + 1):
        ways[i] = 1

    # Iterate through all possible starting sums from 1 to n
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            if i == j:
                continue

            # Calculate the difference between j and i
            diff = j - i

            # If the difference exists in the list and is less than or equal to n
            if diff <= n:
                ways[diff] += ways[i]

    return ways[n]
