def answer(a, b):
    # Calculate the greatest common divisor (GCD) using Euclidean algorithm
    def gcd(x, y):
        while(y):
            x, y = y, x % y

        return abs(x)

    # Calculate the least common multiple (LCM) using formula LCM(a, b) = |a*b| / GCD(a, b)
    def lcm(x, y):
        return abs(x*y)//gcd(x, y)

    # Find the smallest number greater than or equal to 'a' and divisible by 'b'
    n = (lcm(a, b))//gcd(a, b)

    # Return the result as a tuple
    return (n, n*a/b)
