def find_Min(arr, low, high):
    # Base case: if there's only one element or no elements
    if high < low:
        return float('inf')

    # Find the middle index
    mid = (low + high) // 2

    # If the middle element is greater than the last element, all elements on the left side are non-decreasing
    if arr[mid] > arr[high]:
        return find_Min(arr, low, mid)

    # If the middle element is less than the last element, we need to check the whole right side
    elif arr[mid] < arr[high]:
        return find_Min(arr, mid + 1, high)

    # If both conditions are satisfied, the middle element is the minimum
    else:
        return arr[mid]
```

