def max_path_sum(triangle, r, c):
    # Initialize a DP array where dp[i][j] represents the maximum sum of paths ending at position (i, j)
    dp = [[0] * (c + 1) for _ in range(r + 1)]

    # Fill the DP table
    for i in range(1, r+1):
        for j in range(1, c+1):
            if i > 1:
                dp[i][j] = max(dp[i-1][j], dp[i-1][j-1]) + triangle[i-1][j-1]
            elif i == 1:
                dp[i][j] = triangle[i-1][j-1] + j
            elif j == 1:
                dp[i][j] = triangle[i-1][j]

    # Return the maximum value found in the last row of the DP table
    return max(max(row) for row in dp)
```

