def count_common(words):
    # Create a dictionary to count occurrences of each word
    word_counts = {}

    for word in words:
        if word in word_counts:
            word_counts[word] += 1
        else:
            word_counts[word] = 1

    # Return the most common words along with their counts
    most_common_words = []
    max_count = max(word_counts.values())

    for word, count in word_counts.items():
        if count == max_count:
            most_common_words.append((word, count))

    return most_common_words
```

