def calculate_polygons(n, m, r, c, d):
    # Create a grid of points using nested loops
    points = []
    for i in range(n):
        row = []
        for j in range(m):
            if (i // r) + (j // c) == d:
                row.append([i, j])
        points.append(row)

    return points
```
